@startuml

class Well {
  + code : string
}

class OnshoreWell extends Well {
  + surfaceExtension : float
}

class OffshoreWell extends Well {
  + yearOfInstallation : int
  + geographicalArea : string
}

class GeographicalArea {
  + code : string
  + environmentalImportance : int
}

class Company {
  + taxCode : string
  + numberOfEmployees : int
}

class Extraction {
  + quantity : float
}

Well "1" -- "*" Extraction
Company "1" -- "*" Extraction
Extraction "*" -- "1" Well
Extraction "*" -- "1" Company
OffshoreWell "0..1" -- "1" GeographicalArea

@enduml

